def best_rent(rents):
    n = len(rents)
    if n <= 3:
        return max(rents)

    def row(lo, hi):
        a = b = c = 0
        for i in range(lo, hi + 1):
            a, b, c = b, c, max(c, a + rents[i])
        return c

    best = row(3, n - 1)
    for k in range(3):
        best = max(best, rents[k] + row(k + 3, n - 3 + k))
    return best

