def best_rent(rents):
    n = len(rents)
    if n <= 2:
        return max(rents)

    def row(lo, hi):
        a = b = 0
        for i in range(lo, hi + 1):
            a, b = b, max(b, a + rents[i])
        return b

    return max(row(0, n - 2), row(1, n - 1))
